// Read whatever the client's form plugin posted into a known shape.
// Form builders disagree on field names, so accept the common ones rather than
// making every client rename their fields.
const b = ($input.first().json || {}).body || {};
const pick = (...keys) => {
  for (const k of keys) {
    const v = b[k] ?? b[k.toLowerCase()] ?? b[k.toUpperCase()];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return null;
};

const e164 = (v) => {
  const d = String(v || '').replace(/[^\d+]/g, '');
  if (/^\+\d{10,15}$/.test(d)) return d;
  if (/^1\d{10}$/.test(d)) return '+' + d;
  if (/^\d{10}$/.test(d)) return '+1' + d;
  return null;
};

// Which client's form is this? The site embeds their tracked number, same key
// every other T workflow uses, so onboarding sets one field and not two.
const forNumber = e164(pick('business_number', 'to', 'client_number', 'inbound_number'));
const phone = e164(pick('phone', 'tel', 'telephone', 'mobile', 'phone_number', 'your-phone'));
const email = pick('email', 'e-mail', 'email_address', 'your-email');
const name = pick('name', 'full_name', 'fullname', 'your-name', 'first_name');
const message = pick('message', 'comments', 'details', 'description', 'how_can_we_help', 'your-message');

if (!forNumber) {
  return [{ json: { invalid: true, error: 'the form did not say which business it belongs to' } }];
}
if (!phone && !email) {
  return [{ json: { invalid: true, error: 'no phone and no email - nothing to follow up with' } }];
}

return [{ json: {
  invalid: false, for_number: forNumber, phone, email, name,
  message: message || '(no message)',
} }];

/**
 * The one gate every outbound message passes through.
 *
 * T1 grew its own version of this inline, and copying that node into five more
 * workflows would give five copies that drift. This is the single source: the
 * build scripts in n8n/build/ inline it into each workflow's Code node, and
 * outbound-guard.test.mjs is what proves it still does what it claims.
 *
 * Four questions, in this order. Any "no" stops the send.
 *
 *   1. Did they buy it?      A cancelled add-on must stop the software the same
 *                            day it stops the invoice.
 *   2. Is the client on?     workflow_enabled and status - the kill switch.
 *   3. Did they ask for it?  consent_source on the lead. An AI voice is an
 *                            artificial voice under the TCPA; calling a mobile
 *                            without prior express consent runs $500-$1,500 per
 *                            call. Texts carry the same exposure.
 *   4. Is it a decent hour?  8am-9pm in the CLIENT's timezone, since the person
 *                            being contacted just dialled a local business.
 *   5. Have they said stop?  Permanent, per client, honoured immediately.
 *
 * Deliberately returns a reason on refusal rather than a bare false: the
 * execution log is where you find out why a client's customer heard nothing,
 * and "blocked" without a why is a support ticket.
 */

/** Consent kinds that permit us to start a conversation, by channel. */
const CONSENT_FOR_VOICE = ['web_form', 'inbound_call', 'inbound_sms', 'chat'];
const CONSENT_FOR_SMS = ['web_form', 'inbound_call', 'inbound_sms', 'chat', 'existing_customer'];

/**
 * @param {object} o
 * @param {object} o.client        the sanaku_clients row
 * @param {boolean} o.hasAddon     result of sanaku_has_addon()
 * @param {boolean} o.suppressed   a row exists in sanaku_client_suppression
 * @param {string=} o.consentSource lead.consent_source
 * @param {string} o.channel       'sms' | 'voice'
 * @param {Date=} o.now            injectable so the tests are not time-of-day flaky
 * @returns {{maySend:boolean, reason:string|null, localTime:string, afterHours:boolean}}
 */
function outboundGuard({ client, hasAddon, suppressed, consentSource, channel, now }) {
  const at = now || new Date();
  const tz = (client && client.timezone) || 'America/Los_Angeles';

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit',
  }).formatToParts(at);
  const get = (t) => parts.find((p) => p.type === t).value;
  // Node resolves hour12:false to hourCycle h23, so this reads 00-23 and the
  // modulo never fires. It is here because h24 is a real hour cycle (01-24) and
  // a runtime resolving to it would read midnight as 24, i.e. "later than 21",
  // and silently refuse to send for an hour every night. Cheap insurance.
  const hour = Number(get('hour')) % 24;
  const minute = Number(get('minute'));
  const dow = get('weekday').toLowerCase();
  const localTime = String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0') + ' ' + tz;

  // after_hours is the CLIENT's own opening hours - a billing and renewal
  // signal, and a different question from whether we are allowed to send.
  const span = ((client && client.business_hours) || {})[dow];
  let afterHours = true;
  if (Array.isArray(span) && span.length === 2) {
    const toMin = (s) => Number(String(s).split(':')[0]) * 60 + Number(String(s).split(':')[1] || 0);
    const mins = hour * 60 + minute;
    afterHours = !(mins >= toMin(span[0]) && mins < toMin(span[1]));
  }

  const refuse = (reason) => ({ maySend: false, reason, localTime, afterHours });

  if (!client || !client.id) return refuse('no client matched');
  if (!hasAddon) return refuse('this client has not bought this service, or cancelled it');
  if (client.workflow_enabled !== true || client.status !== 'active') {
    return refuse('client paused (kill switch)');
  }

  const allowed = channel === 'voice' ? CONSENT_FOR_VOICE : CONSENT_FOR_SMS;
  if (!consentSource || allowed.indexOf(consentSource) === -1) {
    return refuse(
      'no consent on record' + (consentSource ? ' valid for ' + channel + ' (' + consentSource + ')' : '')
    );
  }

  if (suppressed) return refuse('this person has opted out');

  // Quiet hours are a deferral, not a rejection: the lead is already captured,
  // only the send waits. Callers should re-try rather than drop.
  if (!(hour >= 8 && hour < 21)) return refuse('outside the 8am-9pm window (' + localTime + ')');

  return { maySend: true, reason: null, localTime, afterHours };
}

// Everything the send decision needs, gathered in one place so the execution log
// shows exactly why a message did or did not go out.
const client = $('Find Client').first().json;
const form = $('Normalize Submission').first().json;

// PostgREST returns a bare JSON scalar for an rpc that returns boolean, and n8n
// wraps a non-object body differently depending on version. Read every shape it
// can arrive in, and treat anything unrecognised as NO.
//
// Failing closed matters here: this is what stops a workflow running for a
// client who cancelled. An unreadable answer must never read as "yes".
function readBool(items) {
  const j = (items && items[0] && items[0].json);
  if (j === true || j === 'true') return true;
  if (j && typeof j === 'object') {
    for (const k of ['sanaku_has_addon', 'data', 'result', 'value']) {
      if (j[k] === true || j[k] === 'true') return true;
    }
  }
  return false;
}

// Both lookups run with alwaysOutputData, so an empty result is still one item.
const hasAddonResult = readBool($('Has The Add-On?').all());
const suppressed = ($('Check Suppression').all() || []).some((i) => i.json && i.json.id);

// A form submission IS the consent - they typed their number into the client's
// own website asking to be contacted about this job.
const g = outboundGuard({
  client,
  hasAddon: hasAddonResult,
  suppressed,
  consentSource: 'web_form',
  channel: 'sms',
});

const brand = client.brand_name || client.company_name;

return [{ json: {
  client_id: client.id,
  brand,
  from_number: client.sending_number || client.inbound_number,
  to_number: form.phone,
  name: form.name,
  email: form.email,
  message: form.message,
  after_hours: g.afterHours,
  may_send: g.maySend && !!form.phone,
  block_reason: g.reason,
  local_time: g.localTime,
  escalation_phone: client.escalation_phone,
  reply: 'Thanks for getting in touch with ' + brand + " - we've got your message and will come back to you"
       + (g.afterHours ? ' first thing.' : ' shortly.')
       + '\n\nReply STOP to opt out.',
} }];

// Read the grader's JSON, and fail toward capturing the lead.
// A model that returns prose must not cost the client a customer, so an
// unreadable answer means "keep it, unqualified" rather than "drop it".
let out = { qualified: false, score: 0, urgent: false, summary: '' };
try {
  const raw = $input.first().json.choices[0].message.content;
  const m = String(raw).match(/\{[\s\S]*\}/);
  // No braces at all is the common failure - the model answered in prose and
  // threw nothing. That has to land in the same place as a parse error, or the
  // owner gets an alert with a blank summary and no clue why.
  if (!m) throw new Error('no JSON in the reply');
  out = { ...out, ...JSON.parse(m[0]) };
} catch (e) {
  out.summary = 'could not grade automatically - read the message yourself';
}
const g = $('Guard').first().json;
return [{ json: { ...g, ...out } }];

const g = $('Grade Submission').first().json;
const row = $input.first().json;

const lines = [];
lines.push((g.urgent ? 'URGENT web enquiry' : 'New web enquiry') + (g.after_hours ? ' (after hours)' : ''));
if (g.name) lines.push('Who: ' + g.name);
if (g.to_number) lines.push('Call back: ' + g.to_number);
if (g.email) lines.push('Email: ' + g.email);
lines.push('', String(g.message).slice(0, 300));
if (!g.may_send) lines.push('', 'We did NOT text them: ' + g.block_reason);

return [{ json: {
  send: !!g.escalation_phone && (g.qualified || g.urgent || !g.after_hours),
  to: g.escalation_phone,
  from: g.from_number,
  body: lines.join('\n'),
  lead_id: (row && row.id) || null,
} }];
